// Normaliza el payload del webhook y construye los 3 emails por cuello.
// COPYS: borrador del cerebro (sistema/radiografia-recorrido.md §2). Cuando Ventas publique
// ventas/radiografia/ en su rama, se sustituyen aquí (solo este nodo).
const entrada = $('Entrada: radiografía completada').first().json;
const b = entrada.body || entrada;
if (!b.contact_id) throw new Error('Payload sin contact_id — revisar el webhook del workflow de entrada de GHL (Landing).');

const quitarAcentos = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
let cuelloRaw = b.cuello;
if (!cuelloRaw && Array.isArray(b.tags)) cuelloRaw = (b.tags.find((t) => /^cuello-/.test(t)) || '').replace('cuello-', '');
const CUELLOS = ['captacion', 'conversion', 'seguimiento', 'dependencia', 'control', 'ninguno'];
const cuello = CUELLOS.includes(quitarAcentos(cuelloRaw)) ? quitarAcentos(cuelloRaw) : 'ninguno';
const BONITO = { captacion: 'captación', conversion: 'conversión', seguimiento: 'seguimiento', dependencia: 'dependencia', control: 'control', ninguno: 'sin cuello claro' };

const PREGUNTA = {
  captacion: '¿cuántas oportunidades nuevas os entraron el mes pasado?',
  conversion: 'cuando entra un formulario o un WhatsApp, ¿cuánto tarda en contestarse de media?',
  seguimiento: '¿cuántos presupuestos del mes pasado siguen sin respuesta?',
  dependencia: 'si mañana entraran 30 oportunidades, ¿cuántas se atenderían sin pasar por ti?',
  control: '¿de qué canal salió el último cliente que firmó? El último cliente, no el último lead.',
  ninguno: '¿qué pieza se caería primero si entrara el triple de trabajo?',
};

// Día 3: caso con número + acción que puede hacer hoy sin nosotros.
const DIA3 = {
  captacion: { caso: 'BelloVinilo', cuerpo: 'El error más común en captación no es invertir poco: es atraer a cualquiera.\n\nEn BelloVinilo no tocamos primero el presupuesto: afinamos a quién entraba. De 3.600 € al mes pasaron a 30.000 €.\n\nAcción que puedes hacer hoy sin nosotros: coge los últimos 10 clientes que firmaron y apunta de qué canal salió cada uno. Donde salgan 6 o más, ahí va tu próximo euro.' },
  conversion: { caso: 'Eleva', cuerpo: 'El error más común en conversión no es el anuncio: es contestar tarde a quien ya levantó la mano.\n\nEn Eleva el 61% del presupuesto se iba en leads que no cualificaban; filtrando y contestando en minutos, hoy hacen el doble de entrevistas con la mitad.\n\nAcción que puedes hacer hoy sin nosotros: mira cuánto tardó en contestarse el último formulario que os entró. Si son más de 15 minutos, ahí está la fuga.' },
  seguimiento: { caso: 'Nuria', cuerpo: 'El error más común en seguimiento: presupuestos que nadie persigue.\n\nNuria multiplicó por 6,45 lo que sacaba de cada euro cuando cada presupuesto pasó a tener fecha de siguiente toque.\n\nAcción que puedes hacer hoy sin nosotros: cuenta los presupuestos del mes pasado sin respuesta y ponle a cada uno una fecha de llamada esta semana.' },
  dependencia: { caso: 'EAC', cuerpo: 'El error más común en dependencia: que todo pase por el dueño, también lo que no debería.\n\nEAC multiplicó por 10,2 el retorno cuando el sistema pasó a captar, cualificar y perseguir solo, y el dueño entraba únicamente a cerrar.\n\nAcción que puedes hacer hoy sin nosotros: apunta las 3 tareas comerciales que solo sabes hacer tú y documenta una de ellas hoy en un folio.' },
  control: { caso: 'Equipzilla', cuerpo: 'El error más común en control: invertir sin saber qué funciona.\n\nEn Equipzilla el ROAS estaba en 0,1; midiendo canal a canal y cortando lo que no rendía, llegó a 7,6.\n\nAcción que puedes hacer hoy sin nosotros: averigua de qué canal salió tu último cliente firmado. Si no lo sabes en 5 minutos, esa es la fuga.' },
  ninguno: { caso: 'Eleva', cuerpo: 'Cuando no sale un cuello claro, casi siempre es que aún no hay un número que lo señale.\n\nEn Eleva el número apareció al medir: el 61% del presupuesto se iba en leads que no cualificaban. Hoy hacen el doble de entrevistas con la mitad.\n\nAcción que puedes hacer hoy sin nosotros: elige la pieza que se caería primero si entrara el triple de trabajo y ponle un número esta semana.' },
};

// Día 7: qué se hizo, en qué orden, qué número cambió + oferta del análisis por escrito.
const DIA7 = {
  captacion: 'En BelloVinilo hicimos tres cosas, en este orden: definir a quién NO queríamos, mensaje solo para los que sí, y escalar únicamente lo que traía firmas. El número que cambió: de 3.600 € a 30.000 € al mes.',
  conversion: 'En Eleva hicimos tres cosas, en este orden: filtro de cualificación en el formulario, respuesta automática en minutos, y a entrevista solo los que cumplían. El número que cambió: −61% de coste por lead y el doble de entrevistas.',
  seguimiento: 'Con Nuria hicimos tres cosas, en este orden: inventario de presupuestos vivos, cadencia de seguimiento con fechas, y plantillas para que perseguir no dependiera de acordarse. El número que cambió: 6,45 € de vuelta por cada euro.',
  dependencia: 'En EAC hicimos tres cosas, en este orden: documentar el proceso comercial, sistemas que captan y cualifican solos, y el dueño solo entra a cerrar. El número que cambió: 10,2× de retorno.',
  control: 'En Equipzilla hicimos tres cosas, en este orden: medición canal a canal, cortar lo que no rendía, y reinvertir en lo que sí. El número que cambió: ROAS de 0,1 a 7,6 con un CAC un 80% menor.',
  ninguno: 'En Eleva hicimos tres cosas, en este orden: medir, filtrar y contestar en minutos. El número que cambió: −61% de coste por lead y el doble de entrevistas.',
};

const nombre = String(b.nombre || '').trim();
const primerNombre = nombre.split(' ')[0] || '';
const saludo = primerNombre ? `Hola ${primerNombre},` : 'Hola,';
const puntos = b.puntos != null && b.puntos !== '' ? String(b.puntos) : null;
const tieneWhatsapp = Boolean(b.whatsapp || b.telefono_whatsapp);
const cb = BONITO[cuello];

const email1 = `${saludo} soy Maikel. Vi que en la radiografía te salió ${cb} como cuello de botella${puntos ? `, ${puntos} de 100` : ''}. Una pregunta rápida: ${PREGUNTA[cuello]} Si me dices el número, te digo en dos líneas cuánto es eso al año.`;
const email3 = `${saludo}\n\n${DIA3[cuello].cuerpo}\n\nSi quieres, te digo cuánto es en tu caso: responde con el número.`;
const email7 = `${saludo}\n\n${DIA7[cuello]}\n\nTe hago el análisis por escrito de dónde se te escapa y qué arreglar primero. Sin llamada, sin compromiso. ¿Te lo mando?`;
const aHtml = (t) => t.replace(/\n/g, '<br>');

return [{
  json: {
    contact_id: b.contact_id,
    email: b.email || null,
    nombre, primerNombre,
    empresa: b.empresa || b.web || '',
    cuello, cuelloBonito: cb, puntos, tieneWhatsapp,
    email1_asunto: `tu radiografía: ${cb}`,
    email1_html: aHtml(email1),
    email3_asunto: `el error más común en ${cb}`,
    email3_html: aHtml(email3),
    email7_asunto: `cómo lo arreglamos en ${DIA3[cuello].caso}`,
    email7_html: aHtml(email7),
  },
}];

// Se queda con la oportunidad abierta del contacto (la crea el workflow de entrada de Landing).
const r = $input.first().json;
const opps = r.opportunities || r.data || [];
const abierta = opps.find((o) => (o.status || '').toLowerCase() === 'open') || opps[0];
return [{ json: { opportunity_id: abierta ? abierta.id : null } }];
